import{_ as a,o as l,c as i,ak as s}from"./chunks/framework.DJ-92fJv.js";const u=JSON.parse('{"title":"🔓 一键解锁所有限制","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/unlock-all.md","filePath":"features/unlock-all.md"}'),n={name:"features/unlock-all.md"};function o(c,e,d,r,t,p){return l(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="🔓-一键解锁所有限制" tabindex="-1">🔓 一键解锁所有限制 <a class="header-anchor" href="#🔓-一键解锁所有限制" aria-label="Permalink to “🔓 一键解锁所有限制”">​</a></h1><p><strong>主菜单选项：<code>1</code></strong></p><p>一键解锁是 OsEasy-ToolKit 的核心功能，也是新手的<strong>最佳入口</strong>。它会自动按顺序执行所有解锁操作，彻底解放被限制的电脑。</p><h2 id="执行流程" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程" aria-label="Permalink to “执行流程”">​</a></h2><p>脚本会按以下 5 个步骤依次执行：</p><h3 id="步骤-1-解锁网络限制" tabindex="-1">步骤 1：解锁网络限制 <a class="header-anchor" href="#步骤-1-解锁网络限制" aria-label="Permalink to “步骤 1：解锁网络限制”">​</a></h3><ul><li>停止 <code>MMPC</code> 服务（学生端根服务）</li><li>停止 <code>OeNetlimit</code> 服务（网络限制服务）</li><li>终止 <code>Student.exe</code> 进程</li><li>终止 <code>DeviceControl_x64.exe</code> 进程</li></ul><h3 id="步骤-2-解锁控屏限制" tabindex="-1">步骤 2：解锁控屏限制 <a class="header-anchor" href="#步骤-2-解锁控屏限制" aria-label="Permalink to “步骤 2：解锁控屏限制”">​</a></h3><ul><li>终止 <code>ScreenRender.exe</code> 进程（屏幕广播）</li><li>终止 <code>ScreenRender_Y.exe</code> 进程（屏幕广播辅助）</li><li>重命名 <code>ScreenRender.exe</code> 为 <code>.bak</code> 后缀（防止自动重启）</li></ul><h3 id="步骤-3-解锁键盘鼠标锁" tabindex="-1">步骤 3：解锁键盘鼠标锁 <a class="header-anchor" href="#步骤-3-解锁键盘鼠标锁" aria-label="Permalink to “步骤 3：解锁键盘鼠标锁”">​</a></h3><ul><li>自动检测噢易安装路径</li><li>终止 <code>BlackSlient.exe</code> 进程</li><li>终止 <code>MultiClient.exe</code> 进程</li><li>删除键盘锁驱动文件： <ul><li><code>LockKeyboard.dll</code></li><li><code>LoadDriver.exe</code></li><li><code>BlackSlient.exe</code></li><li><code>LISSNetInfoSniffer.exe</code>（x86目录）</li></ul></li></ul><h3 id="步骤-4-解锁usb限制" tabindex="-1">步骤 4：解锁USB限制 <a class="header-anchor" href="#步骤-4-解锁usb限制" aria-label="Permalink to “步骤 4：解锁USB限制”">​</a></h3><ul><li>停止 <code>easyusbflt</code> 服务（USB管控服务）</li><li>删除 <code>easyusbflt</code> 服务</li></ul><h3 id="步骤-5-清理残留进程" tabindex="-1">步骤 5：清理残留进程 <a class="header-anchor" href="#步骤-5-清理残留进程" aria-label="Permalink to “步骤 5：清理残留进程”">​</a></h3><p>逐一强制终止以下所有进程：</p><details class="details custom-block"><summary>点击展开完整进程列表</summary><ul><li><code>Student.exe</code></li><li><code>MultiClient.exe</code></li><li><code>ScreenRender.exe</code></li><li><code>ScreenRender_Y.exe</code></li><li><code>DeviceControl_x64.exe</code></li><li><code>BlackSlient.exe</code></li><li><code>OELogSystem.exe</code></li><li><code>OEUpdate.exe</code></li><li><code>OEProtect.exe</code></li><li><code>ProcessProtect.exe</code></li><li><code>RunClient.exe</code></li><li><code>ServerOSS.exe</code></li><li><code>wfilesvr.exe</code></li><li><code>tvnserver.exe</code></li><li><code>updatefilesvr.exe</code></li></ul></details><h2 id="执行前倒计时" tabindex="-1">执行前倒计时 <a class="header-anchor" href="#执行前倒计时" aria-label="Permalink to “执行前倒计时”">​</a></h2><p>选择一键解锁后，脚本会显示 <strong>10 秒倒计时</strong>，你可以按任意键立即开始执行，无需等待。</p><h2 id="执行完毕后的提示" tabindex="-1">执行完毕后的提示 <a class="header-anchor" href="#执行完毕后的提示" aria-label="Permalink to “执行完毕后的提示”">​</a></h2><p>解锁完成后屏幕会显示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[√] 所有限制已解锁！</span></span>
<span class="line"><span></span></span>
<span class="line"><span>提示：</span></span>
<span class="line"><span>- 网络限制已解除，可以正常上网</span></span>
<span class="line"><span>- 控屏程序已终止，不会被远程控制</span></span>
<span class="line"><span>- 键盘鼠标锁已删除，输入设备已恢复</span></span>
<span class="line"><span>- USB限制已解除，可以正常使用U盘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>注意：学生端可能会自动重启，如需保持解锁状态，</span></span>
<span class="line"><span>      请使用&quot;进程管理&quot;功能持续监控。</span></span></code></pre></div><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to “使用场景”">​</a></h2><ul><li>✅ <strong>初次使用</strong>：对工具不熟悉时直接选择此项</li><li>✅ <strong>上课被控</strong>：老师开启屏幕广播后快速摆脱控制</li><li>✅ <strong>一劳永逸</strong>：配合持续监控模式使用，效果更佳</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">建议</p><p>一键解锁后，如果发现学生端自动重启（部分版本有进程保护），请立刻进入 <strong>进程管理 → 持续监控模式</strong>（选项 11）来维持解锁状态。</p></div>`,25)])])}const x=a(n,[["render",o]]);export{u as __pageData,x as default};
